// Condense the HTML DOM into a structural skeleton for LLM analysis
const html = $input.first().json.data || $input.first().json.body || '';
const targetUrl = $('Set Parameters').first().json.targetUrl;

// Simple DOM condensation: strip scripts/styles, keep structure
let cleaned = html
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<iframe[^>]*>[\s\S]*?<\/iframe>/gi, '')
  .replace(/<noscript[^>]*>[\s\S]*?<\/noscript>/gi, '')
  .replace(/<svg[^>]*>[\s\S]*?<\/svg>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/<img[^>]*>/gi, '<img>')
  .replace(/<br\s*\/?>/gi, '')
  .replace(/<hr\s*\/?>/gi, '')
  .replace(/\s+/g, ' ')
  .trim();

// Truncate to ~10KB for LLM context window
if (cleaned.length > 10000) {
  cleaned = cleaned.substring(0, 10000) + '\n<!-- ... truncated ... -->';
}

return [{
  json: {
    targetUrl,
    domSkeleton: cleaned,
    domLength: cleaned.length
  }
}];

values.content:
You are an expert web scraper analyst for Arabic news websites. Given a condensed HTML DOM structure, identify the CSS selectors needed to scrape news articles.

Your output MUST be ONLY valid JSON with this structure:
{
  "strategy": "html",
  "confidence": 0.0 to 1.0,
  "reasoning": "Brief Arabic explanation",
  "rssUrl": "discovered RSS URL or null",
  "selectors": {
    "list": {
      "container": "CSS selector for each article item",
      "title": "CSS selector for title within container",
      "link": "CSS selector for link within container"
    },
    "article": {
      "title": "CSS selector for article page title",
      "content": "CSS selector for main content area",
      "date": "CSS selector for publication date"
    }
  }
}

Rules:
- Container must match MULTIPLE repeating elements (article cards)
- Title/link selectors are RELATIVE to container
- Prefer class-based selectors
- Look for RSS/feed links and include in rssUrl if found
- If you find <link type="application/rss+xml"> extract its href

=Analyze this news website and return the JSON selectors.

URL: {{ $json.targetUrl }}

DOM structure:
```
{{ $json.domSkeleton }}
```

