// Parse the LLM response and prepare the payload for the aggregator API
const raw = $input.first().json.message?.content || $input.first().json.text || '';

let parsed;
try {
  // Handle markdown code fences
  let jsonStr = raw;
  const fenceMatch = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fenceMatch) jsonStr = fenceMatch[1].trim();
  parsed = JSON.parse(jsonStr);
} catch (e) {
  return [{ json: { success: false, error: `LLM response is not valid JSON: ${e.message}`, raw } }];
}

// Validate structure
if (!parsed.selectors?.list?.container) {
  return [{ json: { success: false, error: 'LLM did not return valid selectors', raw } }];
}

return [{
  json: {
    success: true,
    strategy: parsed.strategy || 'html',
    confidence: parsed.confidence || 0.5,
    reasoning: parsed.reasoning || '',
    rssUrl: parsed.rssUrl || null,
    selectors: parsed.selectors
  }
}];
